package com.robertx22.age_of_exile.airship;
import java.util.List;

/** One subtitle cue per independently generated audio clip: no guessed word timestamps. */
public final class AirshipVoiceScript {
    private AirshipVoiceScript() {}
    public record Cue(String sound,String text,int durationMillis) {}
    public static List<Cue> cues(int stage) { return switch(stage) {
        case 0->List.of(
            new Cue("captain_intro_a","Это ты отправил сигнал с земли? Я капитан «Последнего Рассвета». Мы заметили его и подошли к стоянке. Не бойся, мы тебя не задерживаем. Можешь осмотреть корабль, а можешь уйти, как захочешь.",14710),
            new Cue("captain_intro_b","Если останешься, найди Мару у картографического стола. Она расскажет, куда мы идём. И ещё: если за бортом услышишь знакомый голос, не отвечай сразу. Позови кого-нибудь из команды. Мы пока сами не знаем, откуда он.",19528));
        case 3->List.of(new Cue("captain_welcome","С Марой и Брамом познакомился? Хорошо. Если решишь задержаться, обращайся к любому из нас. А я пока расскажу, почему мы ищем путевой колокол.",11552));
        case 4->List.of(new Cue("captain_echoes","Во время последнего перехода мы потеряли путевой колокол. Возможно, следы его звона сохранились в старых тайниках. Мара пытается разобраться. Помоги ей проверить находки, а дальше решим, куда идти.",17821));
        case 7->List.of(new Cue("captain_choice","Мара ещё разбирается со следами в тайниках. Пока мы не знаем, ведут ли они к колоколу. Как поступим: расскажем об этом всей команде сейчас или сначала обсудим на мостике?",11842));
        case 10->List.of(new Cue("captain_return","Мара сверила находки, Брам закончил настройку якоря. Спасибо за помощь. Колокол мы пока не нашли, но теперь знаем немного больше о пути. Продолжим поиски вместе.",16033));
        case 11->List.of(new Cue("captain_finale","С первыми поручениями разобрались. Спасибо, что помог. На корабле ещё много работы. Если хочешь остаться, поговори с командой — каждый здесь занимается своим делом.",12701));
        default->List.of(new Cue("captain_idle","Как продвигается твоё дело? Когда закончишь, приходи. Чайник на мостике всё ещё работает, если Тик его не разобрал.",8824));}; }
}
